# river beds: cut 1.5-5 m into the valley floor, deeper and wider for larger catchments, with soft banks
big = smoothstep(0.003, 0.05, @catchment)
bed = smoothstep(0.05, 0.3, @river + 0.12 * big * @river / (@river + 0.02))
@bed = bed * @land
@C = @C - (1.5 + 3.5 * big) / 2048 * @bed

names = np.array(["Bush_A", "Bush_B"])
s@name = names[(rand(@ptnum + 0.3) * 2).astype(int)]
a = rand(@ptnum + 1.7) * 2 * PI
@N = set(sin(a), 0 * a, cos(a))
@up = normalize(lerp(set(0, 1, 0), @tn, 0.4))
@pscale = 0.9 + 1.2 * rand(@ptnum + 4.1)

s@name = sprintf("SM_Rock_%02d", (rand(@ptnum + 0.9) * 4).astype(int))
# follow the slope (up tilted 70% towards the terrain normal), sunk in a bit
@up = normalize(lerp(set(0, 1, 0), @tn, 0.7))
a = rand(@ptnum + 3.3) * 2 * PI
@N = normalize(cross(@up, set(sin(a), 0 * a, cos(a))))
@pscale = 0.8 + 3.0 * pow(rand(@ptnum + 5.5), 2)
@P.y -= 0.25 * @pscale

@Cd = pow(clamp(@Cd, 0, 1), 1 / 2.2)
# the preview shows the sea surface, not the sea floor (the height files keep the floor)
uw = @P.y < -0.3
@N = where(uw, set(0, 1, 0), @N)
@P.y = max(@P.y, -0.3)
